from collections import OrderedDict
import six


class MultiDict(OrderedDict):

    def __setitem__(self, key, value, dict_setitem=dict.__setitem__):
        if key in self:
            self.getall(key).append(value)
        else:
            args = [key, [value], dict_setitem] if six.PY2 else [key, [value]]
            super(MultiDict, self).__setitem__(*args)

    def __getitem__(self, item):
        return self.getall(item)[0]

    def getall(self, key):
        """Returns all values for given key"""
        if key in self:
            return super(MultiDict, self).__getitem__(key)
        else:
            raise KeyError(key)

    def get(self, key, default=None):
        """Returns first value for given key"""
        return self[key] if key in self else default

    def items(self):
        """Returns set of all keys and values"""
        for key in self:
            for value in self.getall(key):
                yield key, value
